const { constants } = require('node:fs');
const { lstat, mkdir, open, realpath, rename, unlink } = require('node:fs/promises');
const { randomUUID } = require('node:crypto');
const path = require('node:path');

// Use filesystem-independent keys, including filenames generated by older releases.
async function mediaPath(root, key, createDirectories = false) {
  const parts = key.split('/');
  if (parts.some(part => !part || part === '.' || part === '..' || /[\\:\x00-\x1f]/.test(part))) {
    throw new Error('Invalid media key');
  }
  if (createDirectories) await mkdir(root, { recursive: true });
  if ((await lstat(root)).isSymbolicLink()) throw new Error('Invalid media directory');
  let directory = await realpath(root);
  for (const part of parts.slice(0, -1)) {
    directory = path.join(directory, part);
    if (createDirectories) {
      await mkdir(directory).catch(error => { if (error.code !== 'EEXIST') throw error; });
    }
    if (!(await lstat(directory)).isDirectory()) throw new Error('Invalid media directory');
  }
  return path.join(directory, parts.at(-1));
}

async function readMedia(root, key) {
  const filename = await mediaPath(root, key);
  const before = await lstat(filename, { bigint: true });
  if (!before.isFile()) throw new Error('Invalid media file');
  const file = await open(filename, constants.O_RDONLY | (constants.O_NOFOLLOW || 0) | (constants.O_NONBLOCK || 0));
  try {
    const after = await file.stat({ bigint: true });
    if (!after.isFile() || !after.ino || before.dev !== after.dev || before.ino !== after.ino) {
      throw new Error('Media file changed');
    }
    return await file.readFile();
  } finally {
    await file.close();
  }
}

async function copyMedia(sourceRoot, targetRoot, key) {
  const bytes = await readMedia(sourceRoot, key);
  const target = await mediaPath(targetRoot, key, true);
  const temporary = path.join(path.dirname(target), randomUUID() + '.tmp');
  const file = await open(temporary, 'wx');
  try {
    try { await file.writeFile(bytes); } finally { await file.close(); }
    await rename(temporary, target);
  } finally {
    await unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; });
  }
}

module.exports = { mediaPath, readMedia, copyMedia };
